Suppose the following conditions hold:  egin{enumerate} \item for any given condition $\mathbf{c}$, the target conditional distribution admits a twice continuously differentiable density function $p_{	ext{target}}(\cdot | \mathbf{c})$, which is positive almost everywhere on $\mathbb{R}^{d_{	ext{target}}}$ and the corresponding score function $
abla\log p_{	ext{target}}(\cdot | \mathbf{c})$ is $L(\mathbf{c})$-Lipschitz continuous with  egin{align} \mathbb{E}_{\mathbf{c}\sim\mathbf{C}}[L(\mathbf{c})] = L_1 < \infty. \end{align} \item The target distribution has a finite second moment, i.e.  egin{align} \mathbb{E}_{\mathbf{c}\sim\mathbf{C}} ig[\mathbb{E}_{\mathbf{Y}(0)\sim p_{	ext{target}}(\cdot | \mathbf{c})}||\mathbf{Y}(0)||^2 ig] < M_2 \end{align} for some positive constant $M_2$. \item There exists a small constant $\varepsilon_{	ext{score}}>0$ such that  egin{align}  rac{1}{K}\sum_{k=1}^K\mathbb{E}_{\mathbf{c}\sim\mathbf{C}} igg[\mathbb{E}_{\mathbf{Y}(	au_k)\sim q_{	au_k}(\cdot | \mathbf{c})} ig[||
abla\log q_{	au_k}(\mathbf{Y}(	au_k) | \mathbf{c}) - s_	heta(	au_k, \mathbf{Y}(	au_k), \mathbf{c})||^2 ig] igg] \le \varepsilon_{	ext{score}}^2. \end{align} \end{enumerate} Then, we have  egin{align} &\mathbb{E}_{\mathbf{c}\sim\mathbf{C}}\left[	ext{KL} ig(p_{	ext{target}}(\cdot | \mathbf{c}) || 	ilde p^	heta_{	au_K}(\cdot | \mathbf{c}) ig)ight]
onumber\ &\lesssim \underbrace{e^{- rac{a}{2}T_g^2 - bT_g} ig[M_2 + de^{- rac{a}{2}T_g^2 - bT_g} ig]}_{{	ext(i)}} + \underbrace{(T_g + 1)^3 \varepsilon_{	ext{score}}^2}_{	ext{(ii)}} + \underbrace{\Delta	au(M_2 + d)(T_g + 1)^5}_{	ext{(iii)}} 
onumber\ &\qquad + \underbrace{M_2\Delta	au (T_g + 1)^2 + d\Delta	au  ig[L_1 + (T_g + 1)^4  ig]}_{	ext{(iv)}} + \underbrace{d(\Delta	au)^2(L_1 + T_g + 1)}_{	ext{(v)}}. \end{align}

Suppose the first condition of Proposition~ef{prop: condition_diffusion_KL_bound} holds. Then for the forward process $\{\mathbf{Y}(	au): 	au\in[0, T_g]\}$ in \eqref{eq: forward_SDE_DDPM} and the corresponding score function $\{
abla\log q_	au(\cdot | \mathbf{c}): 	au\in[0, T_g]\}$, we have  egin{align*} &\mathbb{E}_{\mathbf{c}\sim\mathbf{C}} igg[\sum_{k=1}^{K}\int_{	au_{k - 1}}^{	au_{k}} \mathbb{E}_{\mathbf{Y}(	au)\sim q_{	au}(\cdot | \mathbf{c}),\mathbf{Y}(	au_k)\sim q_{	au_k | 	au}(\cdot | \mathbf{Y}(	au), \mathbf{c})}[ ig\| g^2(	au)
abla\log q_{	au}(\mathbf{Y}(	au)|\mathbf{c}) - g^2(	au_k)
abla\log q_{	au_k}(\mathbf{Y}(	au_k)| \mathbf{c})  ig\|]^2\mathrm{d} 	au igg]\ &\lesssim M_2\Delta	au (T_g + 1)^2 + d\Delta	au  ig[L_1 + (T_g + 1)^4  ig]. \end{align*}

Denote the following drift functions of \eqref{eq: piece_reverse_SDE} and \eqref{eq: piece_reverse_SDE_simulation} for simplicity:  egin{align*} 	ilde F(\mathbf{y}, 	au) := 	ilde f(	au)\mathbf{y} + 	ilde g^2(	au) 
abla\log q_{T_g - 	au}(\mathbf{y} | \mathbf{c}),\quad 	ilde F_	heta(	ilde{\mathbf{z}}):= 	ilde f(	au_k)	ilde{\mathbf{z}} + 	ilde g^2(	au_k) s_	heta(T_g - 	au_k, 	ilde{\mathbf{z}}, \mathbf{c}). \end{align*} We first prove Lemma ef{lemma: KL_dt}(a). Consider an auxiliary process $\{	ilde{\mathbf{Y}}^a(	au): 	au\in(	au_k, 	au_{k + 1}]\}$, which also starts from $	ilde{\mathbf{Y}}^a(	au_k) = 	ilde{\mathbf{z}}$, with the dynamic  egin{align} \mathrm{d}	ilde{\mathbf{Y}}^a(	au) &= [	ilde f(	au_k)	ilde{\mathbf{z}} + 	ilde g^2(	au_k) 
abla\log q_{T_g - 	au_k}(	ilde {\mathbf{z}} | \mathbf{c})]\mathrm{d}	au + 	ilde g(	au) \mathrm{d}	ilde{\mathbf{B}}(	au):=	ilde F_a(	ilde{\mathbf{z}})\mathrm{d}	au + 	ilde g(	au) \mathrm{d} 	ilde{\mathbf{B}}(	au). \end{align} Denote by $	ilde p_{	au | 	au_k}^a(\cdot | 	ilde{\mathbf{z}})$ the conditional density of $	ilde{\mathbf{Y}}^a(	au)$ given $	ilde{\mathbf{Y}}^a(	au_k) = 	ilde{\mathbf{z}}$. Then, $	ilde p_{	au | 	au_k}^a(\cdot | 	ilde{\mathbf{z}})$ is a Gaussian density with mean $	ilde {\mathbf{z}} + (	au - 	au_k)	ilde F_a(	ilde{\mathbf{z}})$ and covariance $\int_{	au_k}^{	au}	ilde g^2(s)\mathrm{d} s\cdot I_d$. Note that, for any $	au\in(	au_k, 	au_{k + 1}]$ and $	ilde{\mathbf{z}}\in\mathbb{R}^d$,  egin{align} 	ext{KL} ig(	ilde p_{	au | 	au_k}(\cdot | 	ilde{\mathbf{z}}) || 	ilde p^	heta_{	au | 	au_k}(\cdot | 	ilde{\mathbf{z}}) ig) &= \int_{\mathbb{R}^d} 	ilde p_{	au | 	au_k}(\mathbf{y} | 	ilde{\mathbf{z}}) \log rac{	ilde p_{	au | 	au_k}(\mathbf{y} | 	ilde{\mathbf{z}})}{	ilde p_{	au | 	au_k}^	heta(\mathbf{y} | 	ilde{\mathbf{z}})}\mathrm{d}\mathbf{y}
onumber\ &= 	ext{KL} ig(	ilde p_{	au | 	au_k}(\cdot | 	ilde{\mathbf{z}}) || 	ilde p_{	au | 	au_k}^a(\cdot | 	ilde{\mathbf{z}}) ig) + \int_{\mathbb{R}^d} 	ilde p_{	au | 	au_k}(\mathbf{y} | 	ilde{\mathbf{z}}) \log rac{	ilde p_{	au | 	au_k}^a(\mathbf{y} | 	ilde{\mathbf{z}})}{	ilde p^	heta_{	au | 	au_k}(\mathbf{y} | 	ilde{\mathbf{z}})}\mathrm{d}\mathbf{y}. \end{align} Using a similar argument as in the proof of Lemma 7(2) in \cite{chen2023improved}, we can obtain that, for almost every $	ilde{\mathbf{z}}\in\mathbb{R}^d$,  egin{align*} \lim_{	au	o	au_k+}	ext{KL}(	ilde p_{	au | 	au_k}(\cdot | 	ilde{\mathbf{z}})|| 	ilde p^a_{	au | 	au_k}(\cdot | 	ilde{\mathbf{z}})) = 0. \end{align*} It follows that  egin{align} \mathbb{E}_{	ilde{\mathbf{Y}}(	au_k)\sim 	ilde p_{	au_k}} igg[\lim_{	au	o	au_k+}	ext{KL}(	ilde p_{	au | 	au_k}(\cdot | 	ilde{\mathbf{Y}}(	au_k))|| 	ilde p^a_{	au | 	au_k}(\cdot | 	ilde{\mathbf{Y}}(	au_k))) igg] = 0. \end{align} On the other hand, both $	ilde p^a_{	au | 	au_k}(\cdot | 	ilde{\mathbf{z}})$ and $	ilde p^	heta_{	au | 	au_k}(\cdot | 	ilde{\mathbf{z}})$ are Gaussian densities, and $\int^{	au}_{	au_k}	ilde g^2(u) \mathrm{d} u =[	ilde g^2(	au_k) - a(	au - 	au_k)/2](	au - 	au_k) \le 	ilde g^2(	au_k)(	au - 	au_k)$. Then, for every $	ilde{\mathbf{z}}\in\mathbb{R}^d$,  egin{align*} &\lim_{	au 	o 	au_k+}\int_{\mathbb{R}^d} 	ilde p_{	au | 	au_k}(\mathbf{y} | 	ilde{\mathbf{z}}) \log rac{	ilde p_{	au | 	au_k}^a(\mathbf{y} | 	ilde{\mathbf{z}})}{	ilde p^	heta_{	au | 	au_k}(\mathbf{y} | 	ilde{\mathbf{z}})}\mathrm{d}\mathbf{y}
onumber\ &= \lim_{	au 	o 	au_k+} \int_{\mathbb{R}^d} 	ilde p_{	au | 	au_k}(\mathbf{y} | 	ilde{\mathbf{z}}) igg[ -  rac{\|\mathbf{y} - 	ilde{\mathbf{z}} - (	au - 	au_k)	ilde F_a(	ilde{\mathbf{z}})\|^2}{\int^{	au}_{	au_k}	ilde g^2(u)\mathrm{d} u} +  rac{\|\mathbf{y} - 	ilde{\mathbf{z}} - (	au - 	au_k)	ilde F_	heta(	ilde{\mathbf{z}})\|^2}{	ilde g^2(	au_k)(	au - 	au_k)} igg]\mathrm{d}\mathbf{y}
onumber\ &= \lim_{	au 	o 	au_k+} \int_{\mathbb{R}^d} 	ilde p_{	au | 	au_k}(\mathbf{y} | 	ilde{\mathbf{z}})  rac{	ilde g^2(	au_k) - a(	au - 	au_k)/2 - 	ilde g^2(	au_k)}{[	ilde g^2(	au_k) - a(	au - 	au_k)/2]\cdot 	ilde g^2(	au_k)(	au - 	au_k)}\|\mathbf{y} - 	ilde{\mathbf{z}}\|^2\mathrm{d}\mathbf{y}
onumber\ &\qquad + \lim_{	au 	o 	au_k+}\int_{\mathbb{R}^d}2	ilde p_{	au | 	au_k}(\mathbf{y} | 	ilde{\mathbf{z}}) igg[ rac{	ilde F_a(	ilde{\mathbf{z}})}{	ilde g^2(	au_k) - a(	au - 	au_k)/2} -  rac{	ilde F_	heta(	ilde{\mathbf{z}})}{	ilde g^2(	au_k)} igg]^T(\mathbf{y} - 	ilde{\mathbf{z}})\mathrm{d}\mathbf{y}
onumber\ &\qquad + \lim_{	au 	o 	au_k+}\int_{\mathbb{R}^d}	ilde p_{	au | 	au_k}(\mathbf{y} | 	ilde{\mathbf{z}}) igg[ rac{\|	ilde F_	heta(	ilde{\mathbf{z}})\|^2(	au - 	au_k)}{	ilde g^2(	au_k)} -  rac{\|	ilde F_a(	ilde{\mathbf{z}})\|^2(	au -	au_k)}{	ilde g^2(	au_k) - a(	au - 	au_k)/2} igg]\mathrm{d}\mathbf{y}
onumber\ &\le \lim_{	au 	o 	au_k+}\int_{\mathbb{R}^d}2	ilde p_{	au | 	au_k}(\mathbf{y} | 	ilde{\mathbf{z}}) igg[ rac{	ilde F_a(	ilde{\mathbf{z}})}{	ilde g^2(	au_k) - a(	au - 	au_k)/2} -  rac{	ilde F_	heta(	ilde{\mathbf{z}})}{	ilde g^2(	au_k)} igg]^T(\mathbf{y} - 	ilde{\mathbf{z}})\mathrm{d}\mathbf{y}
onumber\ &\le 2\lim_{	au 	o 	au_k+}  igg\| rac{	ilde F_a(	ilde{\mathbf{z}})}{	ilde g^2(	au_k) - a(	au - 	au_k)/2} -  rac{	ilde F_	heta(	ilde{\mathbf{z}})}{	ilde g^2(	au_k)} igg\|  ig(\mathbb{E}_{	ilde {\mathbf{Y}}(	au)\sim 	ilde p_{	au | 	au_k}(\cdot | 	ilde{\mathbf{z}})}  ig[\|	ilde{\mathbf{Y}}(	au) - 	ilde{\mathbf{z}}\|^2 ig]  ig)^{1/2}
onumber\ &= 0. \end{align*} It follows that  egin{align} \mathbb{E}_{	ilde{\mathbf{Y}}(	au_k)\sim 	ilde p_{	au_k}} igg[\lim_{	au 	o 	au_k+}\int_{\mathbb{R}^d} 	ilde p_{	au | 	au_k}(\mathbf{y} | 	ilde{\mathbf{Y}}(	au_k)) \log rac{	ilde p_{	au | 	au_k}^a(\mathbf{y} | 	ilde{\mathbf{Y}}(	au_k))}{	ilde p^	heta_{	au | 	au_k}(\mathbf{y} | 	ilde{\mathbf{Y}}(	au_k))}\mathrm{d}\mathbf{y} igg] \le 0. \end{align} Combining \eqref{eq: limit_KL_decomposion}, \eqref{eq: limit_KL_auxiliary} and \eqref{eq: limit_KL_Gaussian}, and using the non-negativity property of KL-divergence, we obtain  egin{align*} \mathbb{E}_{	ilde{\mathbf{Y}}(	au_k)\sim	ilde p_{	au_k}}  igg[\lim_{	au 	o 	au_k+}	ext{KL} ig(	ilde p_{	au | 	au_k}(\cdot | 	ilde{\mathbf{Y}}(	au_k)) || 	ilde p^	heta_{	au | 	au_k}(\cdot | 	ilde{\mathbf{Y}}(	au_k)) ig) igg]= 0, \end{align*} which proves Lemma ef{lemma: KL_dt}(a). Next, we consider bounding $ rac{\mathrm{d}}{\mathrm{d}	au}	ext{KL}(	ilde p_{	au | 	au_k}(\cdot | 	ilde{\mathbf{z}})|| 	ilde p^	heta_{	au | 	au_k}(\cdot | 	ilde{\mathbf{z}})$ for Lemma ef{lemma: KL_dt}(b). For any given $	ilde{\mathbf{z}}\in\mathbb{R}^d$, we use the following notations for simplicity,  egin{align*}  ar p_	au:= 	ilde p_{	au | 	au_k}(\cdot | 	ilde{\mathbf{z}}), \quad  ar p^	heta_	au:= 	ilde p^	heta_{	au | 	au_k}(\cdot | 	ilde{\mathbf{z}}). \end{align*} Using the same argument as in the proof of Lemma 6 in \cite{chen2023improved}, we have  egin{align}  rac{\mathrm{d}}{\mathrm{d}	au}	ext{KL}( ar p_	au ||  ar p^	heta_	au) = \int_{\mathbf{y}\in\mathbb{R}^d} \log  rac{ ar p_	au}{ ar p_	au^	heta}\cdot  rac{\partial  ar p_	au}{\partial	au}(\mathbf{y})\mathrm{d} \mathbf{y} - \int_{\mathbf{y}\in\mathbb{R}^d}  rac{ ar p_	au}{ ar p_	au^	heta}\cdot  rac{\partial  ar p^	heta_	au}{\partial	au}(\mathbf{y})\mathrm{d} \mathbf{y}. \end{align} Applying the Fokker-Planck equation to \eqref{eq: piece_reverse_SDE} and \eqref{eq: piece_reverse_SDE_simulation}, we get the evolutions of $ ar p_	au$ and $ ar p^	heta_	au$ as  egin{align*}  rac{\partial  ar p_	au}{\partial	au}(\mathbf{y}) &= 
abla\cdot igg[-	ilde F(\mathbf{y}, 	au)  ar p_	au(\mathbf{y}) +  rac{1}{2}	ilde g^2(	au)
abla  ar p_	au(\mathbf{y}) igg],\  rac{\partial  ar p^	heta_	au}{\partial	au}(\mathbf{y}) &= 
abla\cdot igg[-	ilde F_	heta(	ilde{\mathbf{z}})  ar p^	heta_	au(\mathbf{y}) +  rac{1}{2}	ilde g^2(	au_k)
abla  ar p^	heta_	au(\mathbf{y}) igg]. \end{align*} It again follows from the Fokker-Planck equation that the first term of \eqref{eq: density_KL_dt} can be expressed as  egin{align*} \int_{\mathbf{y}\in\mathbb{R}^d} \log  rac{ ar p_	au}{ ar p_	au^	heta}\cdot  rac{\partial  ar p_	au}{\partial	au}(\mathbf{y})\mathrm{d} \mathbf{y} &= \int_{\mathbf{y}\in\mathbb{R}^d}  ar p_	au(\mathbf{y}) [	ilde F(\mathbf{y}, 	au)]^T
abla\log rac{ ar p_	au}{ ar p_	au^	heta}(\mathbf{y})\mathrm{d} \mathbf{y} -  rac{	ilde g^2(	au)}{2}\int_{\mathbf{y}\in\mathbb{R}^d} [
abla ar p_	au(\mathbf{y})]^T
abla\log rac{ ar p_	au}{ ar p_	au^	heta}(\mathbf{y}) \mathrm{d} \mathbf{y}, \end{align*} and the second term of \eqref{eq: density_KL_dt} as  egin{align*} \int_{\mathbf{y}\in\mathbb{R}^d}  rac{ ar p_	au}{ ar p_	au^	heta}\cdot  rac{\partial  ar p^	heta_	au}{\partial	au}(\mathbf{y})\mathrm{d} \mathbf{y} = \int_{\mathbf{y}\in\mathbb{R}^d}  ar p^	heta_	au(\mathbf{y}) [	ilde F_	heta(	ilde{\mathbf{z}})]^T 
abla rac{ ar p_	au}{ ar p_	au^	heta}(\mathbf{y}) \mathrm{d} \mathbf{y} -  rac{	ilde g^2(	au_k)}{2}\int_{\mathbf{y}\in\mathbb{R}^d} [
abla ar p^	heta_	au(\mathbf{y})]^T
abla rac{ ar p_	au}{ ar p_	au^	heta}(\mathbf{y})\mathrm{d} \mathbf{y}. \end{align*} We compute  egin{align} &\int_{\mathbf{y}\in\mathbb{R}^d}  ar p_	au(\mathbf{y}) [	ilde F(\mathbf{y}, 	au)]^T
abla\log rac{ ar p_	au}{ ar p_	au^	heta}(\mathbf{y})\mathrm{d} \mathbf{y} - \int_{\mathbf{y}\in\mathbb{R}^d}  ar p^	heta_	au(\mathbf{y}) 	ilde F_	heta(	ilde{\mathbf{z}})^T
abla rac{ ar p_	au}{ ar p_	au^	heta}(\mathbf{y}) \mathrm{d} \mathbf{y} 
onumber\ &= \int_{\mathbf{y}\in\mathbb{R}^d}  ar p_	au(\mathbf{y}) [	ilde F(\mathbf{y}, 	au)]^T
abla\log rac{ ar p_	au}{ ar p_	au^	heta}(\mathbf{y})\mathrm{d} \mathbf{y} - \int_{\mathbf{y}\in\mathbb{R}^d}  ar p_	au(\mathbf{y}) 	ilde F_	heta(	ilde{\mathbf{z}})^T
abla\log rac{ ar p_	au}{ ar p_	au^	heta}(\mathbf{y}) \mathrm{d} \mathbf{y}
onumber\ &= \int_{\mathbf{y}\in\mathbb{R}^d}  ar p_	au(\mathbf{y}) [	ilde F(\mathbf{y}, 	au) - 	ilde F_	heta(	ilde{\mathbf{z}})]^T
abla\log rac{ ar p_	au}{ ar p_	au^	heta}(\mathbf{y})\mathrm{d} \mathbf{y} 
onumber\ &\le \int_{\mathbf{y}\in\mathbb{R}^d}  ar p_	au(\mathbf{y})  igg[ rac{1}{C_{KL}} ig\|	ilde F(\mathbf{y}, 	au) - 	ilde F_	heta(	ilde{\mathbf{z}}) ig\|^2 +  rac{C_{	ext{KL}}}{4} igg\|
abla\log rac{ ar p_	au}{ ar p_	au^	heta}(\mathbf{y}) igg\|^2 igg]\mathrm{d} \mathbf{y} 
onumber\ &=  rac{1}{C_{KL}}\mathbb{E}_{ ar{\mathbf{Y}}(	au)\sim ar p_	au}  ig[ ig\|	ilde F( ar{\mathbf{Y}}(	au), 	au) - 	ilde F_	heta(	ilde{\mathbf{z}}) ig\|^2 ig] +  rac{C_{	ext{KL}}}{4}\mathbb{E}_{ ar{\mathbf{Y}}(	au)\sim ar p_	au}  igg[ igg\|
abla\log rac{ ar p_	au( ar{\mathbf{Y}}(	au))}{ ar p_	au^	heta( ar{\mathbf{Y}}(	au))} igg\|^2 igg], \end{align} where the inequality is from the fact that $\mathbf{x}^T\mathbf{y} \le  rac{1}{C_{	ext{KL}}}\|\mathbf{x}\|^2 +  rac{C_{	ext{KL}}}{4}\|\mathbf{y}\|^2$ for any $\mathbf{x}, \mathbf{y}\in\mathbb{R}^d$ and any fixed constant $C_{	ext{KL}} > 0$. In addition, we have  egin{align} & rac{	ilde g^2(	au_k)}{2}\int_{\mathbf{y}\in\mathbb{R}^d} [
abla ar p^	heta_	au(\mathbf{y})]^T
abla rac{ ar p_	au}{ ar p_	au^	heta}(\mathbf{y})\mathrm{d} \mathbf{y} -  rac{	ilde g^2(	au)}{2}\int_{\mathbf{y}\in\mathbb{R}^d} [
abla ar p_	au(\mathbf{y})]^T
abla\log rac{ ar p_	au}{ ar p_	au^	heta}(\mathbf{y}) \mathrm{d} \mathbf{y} 
