abla\log ar p^	heta_	au(\mathbf{y})]^T
abla rac{ ar p_	au}{ ar p_	au^	heta}(\mathbf{y})\mathrm{d} \mathbf{y} -  rac{	ilde g^2(	au)}{2}\int_{\mathbf{y}\in\mathbb{R}^d} ar p_	au(\mathbf{y})[
abla\log ar p_	au(\mathbf{y})]^T
abla\log rac{ ar p_	au}{ ar p_	au^	heta}(\mathbf{y}) \mathrm{d} \mathbf{y}
onumber\ &=  rac{	ilde g^2(	au_k)}{2}\int_{\mathbf{y}\in\mathbb{R}^d} ar p_	au(\mathbf{y})[
abla\log ar p^	heta_	au(\mathbf{y})]^T
abla\log rac{ ar p_	au}{ ar p_	au^	heta}(\mathbf{y})\mathrm{d} \mathbf{y} -  rac{	ilde g^2(	au)}{2}\int_{\mathbf{y}\in\mathbb{R}^d}  ar p_	au(\mathbf{y})[
abla\log ar p_	au(\mathbf{y})]^T
abla\log rac{ ar p_	au}{ ar p_	au^	heta}(\mathbf{y}) \mathrm{d} \mathbf{y}
onumber\ &= - rac{1}{2}\int_{\mathbf{y}\in\mathbb{R}^d}  ar p_	au(\mathbf{y})[	ilde g^2(	au)
abla\log ar p_	au(\mathbf{y}) - 	ilde g^2(	au_k)
abla\log ar p^	heta_	au(\mathbf{y})]^T 
abla\log rac{ ar p_	au}{ ar p_	au^	heta}(\mathbf{y})\mathrm{d} \mathbf{y}
onumber\ &=  rac{1}{2}\int_{\mathbf{y}\in\mathbb{R}^d}  ar p_	au(\mathbf{y})[	ilde g^2(	au_k) - 	ilde g^2(	au)][
abla\log ar p_	au(\mathbf{y})]^T 
abla\log rac{ ar p_	au}{ ar p_	au^	heta}(\mathbf{y})\mathrm{d} \mathbf{y} -  rac{1}{2}\int_{\mathbf{y}\in\mathbb{R}^d}  ar p_	au(\mathbf{y}) 	ilde g^2(	au_k) igg\|
abla\log rac{ ar p_	au}{ ar p_	au^	heta}(\mathbf{y}) igg\|^2\mathrm{d} \mathbf{y}
onumber\ &\le  rac{1}{4C_{	ext{KL}}}\int_{\mathbf{y}\in\mathbb{R}^d}  ar p_	au(\mathbf{y})[	ilde g^2(	au_k) - 	ilde g^2(	au)]^2 ig\|
abla\log ar p_	au(\mathbf{y}) ig\|^2\mathrm{d}\mathbf{y} 
onumber\ &\qquad +  igg[ rac{C_{	ext{KL}}}{4} -  rac{1}{2} 	ilde g^2(	au_k) igg] \int_{\mathbf{y}\in\mathbb{R}^d}  ar p_	au(\mathbf{y})  igg\|
abla\log rac{ ar p_	au}{ ar p_	au^	heta}(\mathbf{y}) igg\|^2\mathrm{d} \mathbf{y}
onumber\ &=  rac{[	ilde g^2(	au_k) - 	ilde g^2(	au)]^2}{4C_{	ext{KL}}} \mathbb{E}_{ ar{\mathbf{Y}}(	au) \sim  ar p_	au}  ig[ ig\|
abla\log ar p_	au( ar{\mathbf{Y}}(	au)) ig\|^2 ig] 
onumber\ &\qquad +  rac{1}{2} igg[ rac{C_{	ext{KL}}}{2}- 	ilde g^2(	au_k) igg] \mathbb{E}_{ ar{\mathbf{Y}}(	au) \sim  ar p_	au} igg\|
abla\log rac{ ar p_	au( ar{\mathbf{Y}}(	au))}{ ar p_	au^	heta( ar{\mathbf{Y}}(	au))} igg\|^2, \end{align} where the inequality is due to $\mathbf{x}^T\mathbf{y} \le  rac{1}{2C_{	ext{KL}}}\|\mathbf{x}\|^2 +  rac{C_{	ext{KL}}}{2}\|\mathbf{y}\|^2$ for any $\mathbf{x}, \mathbf{y}\in\mathbb{R}^d$ and any fixed constant $C_{	ext{KL}} > 0$. Finally, by combining \eqref{eq: KL_dt_part1} and \eqref{eq: KL_dt_part2}, we can infer from \eqref{eq: density_KL_dt} that \eqref{eq: density_KL_dt_bound} holds. This completes the proof of Lemma~ef{lemma: KL_dt}.

